+    private List<String> splitStoredViolations(String text) {
+        List<String> result = new ArrayList<>();
+        int start = 0;
+        for (int i = 0; i < text.length(); i++) {
+            if (text.charAt(i) == '\n' && (i == 0 || text.charAt(i - 1) != '\\')) {
+                int end = i > start && text.charAt(i - 1) == '\r' ? i - 1 : i;
+                result.add(unescape(text.substring(start, end)));
+                start = i + 1;
+            }
+        }
+        if (start < text.length()) {
+            result.add(unescape(text.substring(start)));
+        }
+        return result.stream().filter(line -> !line.isEmpty()).collect(toList());
+    }
