'}, {'type': 'input_text', 'text': '     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming.
     *
     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        if (ruleViolationFileNameStrategy == null) {
            throw new NullPointerException("ruleViolationFileNameStrategy");
        }
        constructorStrategy = ruleViolationFileNameStrategy;
    }

    @Override
    public void initialize(Properties properties) {
        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        integrityMode = parseIntegrity(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "%s=repair requires %s=true",
                    INTEGRITY_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        ruleViolationFileNameStrategy = determineFileNameStrategy(properties);
        storeFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
        storedRulesPath = new File(storeFolder, STORED_RULES_FILE_NAME).toPath();
        storeLock = STORE_LOCKS.computeIfAbsent(canonicalPath(storeFolder), ignored -> new Object());

        synchronized (storeLock) {
            initializeStore();
        }
    }

    private IntegrityMode parseIntegrity(String configuredIntegrity) {
        if ("repair".equals(configuredIntegrity)) {
            return IntegrityMode.REPAIR;
        }
        if ("fail".equals(configuredIntegrity)) {
            return IntegrityMode.FAIL;
        }
        if ("ignore".equals(configuredIntegrity)) {
            return IntegrityMode.IGNORE;
        }
        throw new StoreInitializationFailedException(String.format(
                "%s must be one of repair, fail or ignore, but was '%s'",
                INTEGRITY_PROPERTY_NAME, configuredIntegrity));
    }

    private RuleViolationFileNameStrategy determineFileNameStrategy(Properties properties) {
        if (constructorStrategy != null) {
            if (properties.getProperty(FILE_NAMES_PROPERTY_NAME) != null) {
                throw new StoreInitializationFailedException(String.format(
                        "%s cannot be configured for a store constructed with a RuleViolationFileNameStrategy",
                        FILE_NAMES_PROPERTY_NAME));
            }
            return constructorStrategy;
        }

        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, RANDOM_FILE_NAMES);
        if (RANDOM_FILE_NAMES.equals(configured)) {
            return ignored -> UUID.randomUUID().toString();
        }
        if (DESCRIPTION_FILE_NAMES.equals(configured)) {
            return new DescriptionRuleViolationFileNameStrategy();
        }

        try {
            Class<?> strategyType = Class.forName(configured);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyType)) {
                throw new IllegalArgumentException("not a RuleViolationFileNameStrategy");
            }
            Constructor<?> constructor = strategyType.getConstructor();
            if (!Modifier.isPublic(constructor.getModifiers())) {
                throw new IllegalArgumentException("the no-argument constructor is not public");
            }
            return (RuleViolationFileNameStrategy) constructor.newInstance();
        } catch (Exception e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not instantiate %s configured by %s='%s'; it must have a public no-argument constructor",
                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, configured), e);
        }
    }

    private void initializeStore() {
        log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesPath.toAbsolutePath());

        boolean indexExists = Files.exists(storedRulesPath, LinkOption.NOFOLLOW_LINKS);
        if (!indexExists && !storeCreationAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
        }
        if (indexExists && !Files.isRegularFile(storedRulesPath, LinkOption.NOFOLLOW_LINKS)) {
            throw new StoreInitializationFailedException(String.format(
                    "The stored rules index must be a regular file directly in the store folder: %s",
                    storedRulesPath.toAbsolutePath()));
        }

        boolean folderExists = Files.exists(storeFolder.toPath(), LinkOption.NOFOLLOW_LINKS);
        if (folderExists && !storeFolder.isDirectory()) {
            throw new StoreInitializationFailedException(String.format(
                    "The violation store folder is not a directory: %s", storeFolder.getAbsolutePath()));
        }
        if (!folderExists && integrityMode != IntegrityMode.FAIL) {
            createStoreFolder();
            folderExists = true;
        }

        Properties current = indexExists ? loadProperties() : new Properties();
        if (integrityMode == IntegrityMode.IGNORE) {
            if (!indexExists) {
                writeIndex(current);
            }
            storedRules = current;
            return;
        }

        IntegrityReport report = inspect(current, folderExists);
        if (integrityMode == IntegrityMode.FAIL) {
            if (report.hasProblems()) {
                throw new StoreInitializationFailedException(formatIntegrityFailure(report));
            }
            if (!indexExists) {
                createStoreFolder();
                writeIndex(current);
            }
            storedRules = current;
            return;
        }

        repair(current, report);
        if (!indexExists && !Files.exists(storedRulesPath, LinkOption.NOFOLLOW_LINKS)) {
            createStoreFolder();
            writeIndex(current);
        }
        storedRules = current;
    }

    private void createStoreFolder() {
        if (!storeFolder.mkdirs() && !storeFolder.isDirectory()) {
            throw new StoreInitializationFailedException(String.format(
                    "Cannot create rule store folder %s", storeFolder.getAbsolutePath()));
        }
    }

    private Properties loadProperties() {
        Properties result = new Properties();
        try (FileInputStream inputStream = new FileInputStream(storedRulesPath.toFile())) {
            result.load(inputStream);
            return result;
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private void reloadPropertiesForUpdate() {
        if (!Files.exists(storedRulesPath, LinkOption.NOFOLLOW_LINKS)) {
            if (!storeCreationAllowed) {
                throw new StoreUpdateFailedException("The stored rules index does not exist");
            }
            storedRules = new Properties();
        } else {
            if (!Files.isRegularFile(storedRulesPath, LinkOption.NOFOLLOW_LINKS)) {
                throw new StoreUpdateFailedException("The stored rules index is not a regular file");
            }
            storedRules = loadProperties();
        }
    }

    @Override
    public boolean contains(ArchRule rule) {
        synchronized (storeLock) {
            return storedEntryKey(rule.getDescription()) != null;
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
        if (!storeUpdateAllowed) {
            throw new StoreUpdateFailedException(String.format(
                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        synchronized (storeLock) {
            reloadPropertiesForUpdate();
            String description = rule.getDescription();
            String existingDescription = storedEntryKey(description);
            String existingFileName = existingDescription == null ? null : storedRules.getProperty(existingDescription);
            if (violations.isEmpty() && existingFileName == null) {
                return;
            }
            String candidateFileName = ruleViolationFileNameStrategy.createRuleFileName(description);
            String fileName = existingFileName == null ? requireFileName(candidateFileName) : existingFileName;
            String descriptionKey = existingDescription == null ? description : existingDescription;
            validateNameForSave(fileName, descriptionKey);

            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
                forgetRuleIfStored(descriptionKey, fileName);
            } else {
                write(violations, pathFor(fileName));
                if (existingFileName == null) {
                    Properties before = copyOf(storedRules);
                    storedRules.setProperty(descriptionKey, fileName);
                    try {
                        writeIndex(storedRules);
                    } catch (RuntimeException e) {
                        storedRules = before;
                        throw e;
                    }
                }
            }
        }
    }

    private String requireFileName(String fileName) {
        if (fileName == null || fileName.isEmpty()) {
            throw new StoreUpdateFailedException("The RuleViolationFileNameStrategy returned no file name");
        }
        return fileName;
    }
    }

    private void validateNameForSave(String fileName, String description) {
        Path path = pathFor(fileName);
        if (!isDirectChild(path)) {
            throw new StoreUpdateFailedException(String.format(
                    "The rule violation file name '%s' does not lead directly into the store folder", fileName));
        }
        if (sameFileAsIndex(path)) {
            throw new StoreUpdateFailedException(String.format(
                    "The rule violation file name '%s' leads to the stored rules index", fileName));
        }
        String otherDescription = descriptionForFileName(fileName, description);
        if (otherDescription != null) {
            throw new StoreUpdateFailedException(String.format(
                    "The rule violation file name '%s' is already recorded for rule '%s'", fileName, otherDescription));
        }
    }

    private String descriptionForFileName(String fileName, String ownDescription) {
        for (String description : storedRules.stringPropertyNames()) {
            if (!description.equals(ownDescription) && fileName.equals(storedRules.getProperty(description))) {
                return description;
            }
        }
        return null;
    }

    private void forgetRuleIfStored(String description, String fileName) {
        if (!storedRules.containsKey(description)) {
            return;
        }
        if (!isSharedWithAnotherEntry(description, fileName)) {
            deleteNamedFile(pathFor(fileName));
        }

        Properties before = copyOf(storedRules);
        storedRules.remove(description);
        try {
            writeIndex(storedRules);
        } catch (RuntimeException e) {
            storedRules = before;
            throw e;
        }
    }

    private boolean isSharedWithAnotherEntry(String description, String fileName) {
        Path path = pathFor(fileName);
        for (String otherDescription : storedRules.stringPropertyNames()) {
            if (description.equals(otherDescription)) {
                continue;
            }
            String otherFileName = storedRules.getProperty(otherDescription);
            if (fileName.equals(otherFileName) || sameFile(path, pathFor(otherFileName))) {
                return true;
            }
        }
        return false;
    }

    private void write(List<String> violations, Path ruleDetails) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append("\n");
        }
        try {
            Files.write(ruleDetails, builder.toString().getBytes(UTF_8));
        } catch (IOException | InvalidPathException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private String escape(String violation) {
        return violation.replace("\n", "\\\n");
    }

    private String unescape(String violation) {
        return violation.replace("\\\n", "\n");
    }

    @Override
    public List<String> getViolations(ArchRule rule) {
        synchronized (storeLock) {
            String descriptionKey = storedEntryKey(rule.getDescription());
            String ruleDetailsFileName = descriptionKey == null ? null : storedRules.getProperty(descriptionKey);
            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
            List<String> result = readLines(ruleDetailsFileName);
            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
            return result;
        }
    }

    private List<String> readLines(String ruleDetailsFileName) {
        String violationsText = readStoreFile(ruleDetailsFileName);
        if (violationsText.isEmpty() || violationsText.chars().allMatch(character -> character == '\r' || character == '\n')) {
            return Collections.emptyList();
        }
        return splitStoredViolations(violationsText);
    }

    private List<String> splitStoredViolations(String text) {
        List<String> result = new ArrayList<>();
        int start = 0;
        for (int i = 0; i < text.length(); i++) {
            if (text.charAt(i) == '\n' && (i == 0 || text.charAt(i - 1) != '\\')) {
                int end = i > start && text.charAt(i - 1) == '\r' ? i - 1 : i;
                result.add(unescape(text.substring(start, end)));
                start = i + 1;
            }
        }
        if (start < text.length()) {
            result.add(unescape(text.substring(start)));
        }
        return result.stream().filter(line -> !line.isEmpty()).collect(toList());
    }

    private String readStoreFile(String fileName) {
        try {
            return new String(toByteArray(pathFor(fileName).toFile()), UTF_8);
        } catch (IOException | InvalidPathException e) {
            throw new StoreReadException(e);
        }
    }

    private IntegrityReport inspect(Properties rules, boolean folderExists) {
        List<Entry> entries = rules.stringPropertyNames().stream()
                .map(description -> new Entry(description, rules.getProperty(description)))
                .sorted(Comparator.comparing(entry -> entry.description))
                .collect(toList());

        for (Entry entry : entries) {
            entry.path = pathForDuringInspection(entry.fileName);
            entry.direct = entry.path != null && isDirectChild(entry.path);
            entry.broken = entry.path == null || !entry.direct || !isRegularFile(entry.path);
            if (!entry.broken) {
                try {
                    entry.resolved = readLines(entry.fileName).isEmpty();
                } catch (RuntimeException e) {
                    entry.broken = true;
                }
            }
            entry.derivedFileName = requireInitializationFileName(entry.description);
            entry.misplaced = !entry.fileName.equals(entry.derivedFileName);
        }

        markShared(entries);
        markColliding(entries);
        for (Entry entry : entries) {
            if (entry.misplaced) {
                entry.occupied = isOccupied(entry, entries);
            }
        }

        List<Path> unownedFiles = folderExists ? findUnownedFiles(entries) : Collections.emptyList();
        return new IntegrityReport(entries, unownedFiles);
    }

    private String requireInitializationFileName(String description) {
        try {
            String fileName = ruleViolationFileNameStrategy.createRuleFileName(description);
            if (fileName == null || fileName.isEmpty()) {
                throw new StoreInitializationFailedException(
                        "The RuleViolationFileNameStrategy returned no file name while checking store integrity");
            }
            return fileName;
        } catch (StoreInitializationFailedException e) {
            throw e;
        } catch (RuntimeException e) {
            throw new StoreInitializationFailedException(
                    "The RuleViolationFileNameStrategy could not create a file name while checking store integrity", e);
        }
    }

    private void markShared(List<Entry> entries) {
        for (int i = 0; i < entries.size(); i++) {
            for (int j = i + 1; j < entries.size(); j++) {
                Entry first = entries.get(i);
                Entry second = entries.get(j);
                if (first.fileName.equals(second.fileName) || sameFile(first.path, second.path)) {
