    private void markColliding(List<Entry> entries) {
        Map<String, List<Entry>> byDerivedName = new HashMap<>();
        for (Entry entry : entries) {
            byDerivedName.computeIfAbsent(entry.derivedFileName, ignored -> new ArrayList<>()).add(entry);
        }
        for (List<Entry> collision : byDerivedName.values()) {
            if (collision.size() > 1) {
                collision.forEach(entry -> entry.colliding = true);
            }
        }
