    private boolean isOccupied(Entry entry, List<Entry> entries) {
        Path derivedPath = pathForDuringInspection(entry.derivedFileName);
        if (derivedPath == null || !isDirectChild(derivedPath)) {
            return true;
        }
        if (existsWithoutFollowingLinks(derivedPath)) {
            return true;
        }
        for (Entry other : entries) {
            if (other != entry && entry.derivedFileName.equals(other.fileName)) {
                return true;
            }
        }
        return false;
    }

    private List<Path> findUnownedFiles(List<Entry> entries) {
        File[] files = storeFolder.listFiles();
        if (files == null) {
            throw new StoreInitializationFailedException(String.format(
                    "Cannot list violation store folder %s", storeFolder.getAbsolutePath()));
        }
        List<Path> result = Arrays.stream(files)
                .map(File::toPath)
                .filter(path -> !path.toAbsolutePath().normalize().equals(storedRulesPath.toAbsolutePath().normalize()))
                .filter(path -> Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS))
                .filter(path -> entries.stream().noneMatch(entry -> sameFile(entry.path, path)))
                .sorted(Comparator.comparing(path -> path.getFileName().toString()))
                .collect(toList());
        return result;
    }

    private void repair(Properties rules, IntegrityReport report) {
        boolean indexChanged = false;
        for (Entry entry : report.entries) {
            if (entry.shared) {
                continue;
            }
            if (entry.broken) {
                rules.remove(entry.description);
                indexChanged = true;
            } else if (entry.resolved) {
                deleteNamedFile(entry.path);
                rules.remove(entry.description);
                indexChanged = true;
            } else if (!entry.colliding && !entry.occupied && entry.misplaced) {
                moveNamedFile(entry.path, pathFor(entry.derivedFileName));
                rules.setProperty(entry.description, entry.derivedFileName);
                indexChanged = true;
            }
        }
        if (indexChanged) {
            writeIndex(rules);
        }
    }

    private void deleteNamedFile(Path namedPath) {
        try {
            if (!existsWithoutFollowingLinks(namedPath)) {
                return;
            }
            if (!isRegularFile(namedPath)) {
                throw new StoreInitializationFailedException(String.format(
                        "Cannot delete non-regular violation file %s", namedPath));
            }
            Path target = namedPath.toRealPath();
            Files.delete(target);
            if (!target.equals(namedPath.toAbsolutePath().normalize()) && existsWithoutFollowingLinks(namedPath)) {
                Files.delete(namedPath);
            }
        } catch (IOException | InvalidPathException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Cannot delete violation file %s", namedPath), e);
        }
    }

    private void moveNamedFile(Path source, Path destination) {
        try {
            Path target = source.toRealPath();
            Files.move(target, destination);
            if (!target.equals(source.toAbsolutePath().normalize()) && existsWithoutFollowingLinks(source)) {
                Files.delete(source);
            }
        } catch (IOException | InvalidPathException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Cannot move violation file %s to %s", source, destination), e);
        }
    }

    private String formatIntegrityFailure(IntegrityReport report) {
        StringBuilder result = new StringBuilder();
        result.append("Violation store integrity check failed (")
                .append(ALLOW_STORE_UPDATE_PROPERTY_NAME).append('=').append(storeUpdateAllowed).append("):");
        appendEntries(result, "broken", report.brokenEntries());
        appendEntries(result, "resolved", report.resolvedEntries());
        appendEntries(result, "shared", report.sharedEntries());
        appendEntries(result, "colliding", report.collidingEntries());
        appendEntries(result, "occupied", report.occupiedEntries());
        appendEntries(result, "misplaced", report.misplacedEntries());
        if (!report.unownedFiles.isEmpty()) {
            result.append(" unowned files:");
            for (Path file : report.unownedFiles) {
                result.append(" ").append(file.getFileName());
            }
        }
        return result.toString();
    }

    private void appendEntries(StringBuilder result, String condition, List<Entry> entries) {
        if (entries.isEmpty()) {
            return;
        }
        result.append(' ').append(condition).append(" entries:");
        for (Entry entry : entries) {
            result.append(" [").append(entry.description).append(" -> ").append(entry.fileName).append(']');
        }
    }

    private boolean isRegularFile(Path path) {
