    }

    private boolean existsWithoutFollowingLinks(Path path) {
        try {
            return Files.exists(path, LinkOption.NOFOLLOW_LINKS);
        } catch (InvalidPathException | NullPointerException e) {
            return false;
        }
    }

    private boolean sameFile(Path first, Path second) {
        try {
            return existsWithoutFollowingLinks(first) && existsWithoutFollowingLinks(second) && Files.isSameFile(first, second);
        } catch (IOException | InvalidPathException e) {
