    private static final class DescriptionRuleViolationFileNameStrategy implements RuleViolationFileNameStrategy {
        @Override
        public String createRuleFileName(String ruleDescription) {
            Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(ruleDescription);
            String keptWord = null;
            while (matcher.find()) {
                keptWord = matcher.group(1);
            }
            if (keptWord == null) {
                keptWord = "rule";
            }
            String hash = sha256(ruleDescription);
            return keptWord + "-" + hash;
        }

        private static String sha256(String value) {
            try {
                byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
                StringBuilder result = new StringBuilder(digest.length * 2);
                for (byte valueByte : digest) {
                    result.append(String.format("%02x", valueByte & 0xff));
                }
                return result.toString();
            } catch (NoSuchAlgorithmException e) {
                throw new IllegalStateException(e);
            }
        }
    }

